using UnityEngine; namespace BiniarosAR { public class BiniarosRuntimeUI:MonoBehaviour { public ARPlacementController placement; public Transform pergola; bool showHelp=true; void OnGUI(){GUI.depth=-1000;float s=Mathf.Max(1f,Screen.width/720f);GUI.skin.button.fontSize=Mathf.RoundToInt(22*s);GUI.skin.label.fontSize=Mathf.RoundToInt(22*s);GUI.skin.box.fontSize=Mathf.RoundToInt(18*s);float x=18*s,y=18*s,w=Mathf.Min(Screen.width-x*2,650*s);GUI.Box(new Rect(x,y,w,245*s),"BINIAROS ROMA AR");GUI.Label(new Rect(x+18*s,y+45*s,w-36*s,58*s),RuntimeARBootstrap.Status);if(GUI.Button(new Rect(x+18*s,y+110*s,180*s,58*s),"90°"))placement?.Rotate90();if(GUI.Button(new Rect(x+210*s,y+110*s,180*s,58*s),"RESET"))placement?.ResetPlacement();if(GUI.Button(new Rect(x+18*s,y+178*s,372*s,50*s),showHelp?"ΚΡΥΨΕ ΟΔΗΓΙΕΣ":"ΟΔΗΓΙΕΣ"))showHelp=!showHelp;if(showHelp)GUI.Label(new Rect(18*s,Screen.height-105*s,Screen.width-36*s,90*s),"Σκάναρε αργά το δάπεδο • 1 άγγιγμα: τοποθέτηση • 2 δάχτυλα: περιστροφή • Κλίμακα 1:1");}}}
